(function(root){'use strict';
const C=root.NutriFoodCaptureContract,K=root.NutriFoodCaptureController;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function mount(host,{date,id,initial=null,save,isLocked=()=>false,onDirty=()=>{},start='camera'}={}){let active=true,origin='manual',url=null,selection=0,busy=false;const message=t=>{if(active)host.querySelector('.fc-status').textContent=t;};
host.innerHTML=`<section class="fc-panel"><h2 class="glass-review-title">核对这一餐</h2><p>本机预览，不上传照片。当前仅可保存合成演示记录；照片不存入账号，刷新后清除。</p><nav><button type="button" data-fc="camera">相机</button><button type="button" data-fc="manual">手动输入</button><button type="button" data-fc="gallery">选择图片</button></nav><video class="fc-preview" autoplay muted playsinline hidden></video><img class="fc-preview" alt="仅本机预览的食物照片" hidden><button type="button" data-fc="shutter" hidden>拍照</button><input data-fc-file type="file" accept="image/*" hidden><p class="fc-status" role="status">照片识别与语音服务未连接，可手工填写合成示例。</p><p class="fc-draft-note">未提交的填写只在当前编辑器中，不是已保存草稿；离开前请核对。只有下方确认保存才写入本机合成记录。</p><form data-fc-form><label>食物名称<input name="name" maxlength="100" required></label><div class="fc-grid"><label>摄入日期<input type="date" name="date" value="${esc(date)}" required></label><label>时间<input type="time" name="time" value="12:00" required></label><label>餐次<select name="slot"><option value="breakfast">早餐</option><option value="lunch">午餐</option><option value="dinner">晚餐</option><option value="snack">加餐</option></select></label><label>份量 g（未知留空）<input name="grams" type="number" min="0" step="any"></label></div><section class="fc-nutrition-main" aria-label="编辑本次摄入营养"><h3>编辑营养</h3><p>本次摄入总量 · 手工填写，未知留空；修改克数不会自动换算营养。</p><div class="fc-grid">${Object.entries(C.fields).filter(([k])=>['kcal','protein','carb','fat'].includes(k)).map(([k,[label,unit]])=>`<label>${label} ${unit}<input name="${k}" type="number" min="0" step="any" placeholder="未知留空"></label>`).join('')}</div></section><details><summary>更多营养成分 · 24 项（可选）</summary><div class="fc-grid">${Object.entries(C.fields).filter(([k])=>!['kcal','protein','carb','fat'].includes(k)).map(([k,[label,unit]])=>`<label>${label} ${unit}<input name="${k}" type="number" min="0" step="any" placeholder="未知留空"></label>`).join('')}</div></details><p>钠 mg 与盐 g 分别记录，不互相冒充；空白不是 0。图片不能确定份量、油盐和完整营养。</p><label><input type="checkbox" name="confirmedSynthetic" required>仅保存合成示例；已核对名称、日期、餐次和所填营养值，同意存此浏览器。</label><button type="submit">确认保存合成记录</button></form></section>`;
if(initial){const form=host.querySelector('[data-fc-form]');for(const key of ['name','date','time','slot','grams',...Object.keys(C.fields)]){if(form.elements[key]){const value=initial.nutrients&&Object.prototype.hasOwnProperty.call(initial.nutrients,key)?initial.nutrients[key]?.value:initial[key];form.elements[key].value=value==null?'':String(value);}}}
const video=host.querySelector('video'),img=host.querySelector('img'),shutter=host.querySelector('[data-fc="shutter"]'),file=host.querySelector('[data-fc-file]');
const controller=K.create({mediaDevices:root.navigator?.mediaDevices,onState:(state,e)=>{if(state==='camera-error')message(e?.name==='NotAllowedError'?'相机权限未允许，可手动输入或选择图片。':e?.message||'相机不可用，可手动输入或选择图片。');}});
function stop(){selection++;controller.leave();video.srcObject=null;video.hidden=true;shutter.hidden=true;}
function revoke(){if(url){URL.revokeObjectURL(url);url=null;}}
async function camera(){stop();img.hidden=true;message('正在请求相机权限；可随时切换手动输入。');const s=await controller.camera();if(!active||!s)return;video.srcObject=s;video.hidden=false;shutter.hidden=false;origin='camera';message('只在本机预览。拍照后手工核对；AI识别服务未连接。');video.play().catch(()=>message('请允许视频播放，或改用选择图片/手动记录。'));}
async function acceptFile(blob,source){stop();const ticket=selection;if(!blob||!blob.type.startsWith('image/')){message('请选择有效图片，原填写已保留。');return;}if(blob.size>12*1024*1024){message('图片超过本地 12 MB 限制，请选择较小图片。未上传。');return;}message('正在本地读取图片…');let next=URL.createObjectURL(blob),probe=new Image();try{await new Promise((resolve,reject)=>{probe.onload=resolve;probe.onerror=reject;probe.src=next;});if(!active||ticket!==selection){URL.revokeObjectURL(next);return;}if(probe.naturalWidth*probe.naturalHeight>24000000)throw Error('图片像素过大');revoke();url=next;img.src=url;img.hidden=false;origin=source;onDirty();message('照片已在本机准备好；AI识别未连接。请手工核对，未知营养留空。照片不会保存到演示账号。');}catch(e){URL.revokeObjectURL(next);message('图片无法读取或像素过大，原填写已保留。未上传。');}}
function click(e){const b=e.target.closest('[data-fc]');if(!b)return;e.preventDefault();e.stopPropagation();if(busy)return;if(b.dataset.fc==='camera')camera();if(b.dataset.fc==='manual'){stop();message('手动记录：语音转写未连接，不会录音。');host.querySelector('[name=name]').focus();}if(b.dataset.fc==='gallery'){stop();file.click();}if(b.dataset.fc==='shutter'){if(!video.videoWidth||!video.videoHeight){message('相机尚未准备好');return;}const canvas=document.createElement('canvas'),factor=Math.min(1,1600/video.videoWidth);canvas.width=Math.round(video.videoWidth*factor);canvas.height=Math.round(video.videoHeight*factor);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const captureTicket=selection;canvas.toBlob(blob=>{if(active&&captureTicket===selection)acceptFile(blob,'camera');},'image/jpeg',.85);}}
function change(e){if(e.target===file){const selected=file.files?.[0];file.value='';if(selected)acceptFile(selected,'gallery');return;}onDirty();}
async function submit(e){if(!e.target.matches('[data-fc-form]'))return;e.preventDefault();e.stopPropagation();if(busy||!active||isLocked())return;const f=e.target;if(!f.reportValidity())return;try{const data=Object.fromEntries(new FormData(f));data.confirmedSynthetic=f.elements.confirmedSynthetic.checked;data.origin=origin;let row=C.record(data,id);if(initial){row={...initial,...row,revision:(initial.revision||0)+1,previousRevision:initial.revision||0};for(const key of Object.keys(C.fields)){const old=initial.nutrients?.[key];if(old&&old.value===row.nutrients[key].value)row.nutrients[key]=JSON.parse(JSON.stringify(old));}row.note='人工校对的合成示例修订；非图像识别';}busy=true;f.querySelector('button[type=submit]').disabled=true;stop();await save(row);}catch(err){message(err.message||'保存未确认，请核对原操作；填写保留。');}finally{busy=false;if(active)f.querySelector('button[type=submit]').disabled=isLocked();}}
function hidden(){if(document.hidden)stop();}
host.addEventListener('click',click);host.addEventListener('change',change);host.addEventListener('input',onDirty);host.addEventListener('submit',submit);document.addEventListener('visibilitychange',hidden);
if(start==='camera')camera();else message('语音服务未连接；可直接文字补录，不会录音或转写。');
return{dispose(){active=false;stop();controller.dispose();revoke();host.removeEventListener('click',click);host.removeEventListener('change',change);host.removeEventListener('input',onDirty);host.removeEventListener('submit',submit);document.removeEventListener('visibilitychange',hidden);}};
}
root.NutriFoodCaptureView={mount};
})(window);
